static char *parse_string(const char **p) {
    while (**p && (**p == ' ' || **p == ',' || **p == '[' || **p == '\n' || **p == '\r' || **p == '\t')) (*p)++;
    if (**p != '"') return NULL;
    (*p)++;
    const char *start = *p;
    while (**p && **p != '"') (*p)++;
    size_t n = (size_t)(*p - start);
    char *out = (char *)malloc(n + 1);
    memcpy(out, start, n);
    out[n] = '\0';
    if (**p == '"') (*p)++;
    return out;
}

static int parse_bank(const char **p, char ***out_bank) {
    while (**p && (**p == ' ' || **p == ',' || **p == '\n' || **p == '\r' || **p == '\t')) (*p)++;
    if (**p != '[') return 0;
    (*p)++;
    char **bank = (char **)malloc(10 * sizeof(char *));
    int n = 0;
    for (;;) {
        while (**p && (**p == ' ' || **p == ',' || **p == '\n' || **p == '\r' || **p == '\t')) (*p)++;
        if (**p == ']') { (*p)++; break; }
        char *g = parse_string(p);
        if (!g) break;
        bank[n++] = g;
    }
    *out_bank = bank;
    return n;
}

static int minMutation(char *startGene, char *endGene, char **bank, int bankSize) {
    if (strcmp(startGene, endGene) == 0) return 0;

    int endIndex = -1;
    for (int i = 0; i < bankSize; ++i) {
        if (strcmp(bank[i], endGene) == 0) { endIndex = i; break; }
    }
    if (endIndex < 0) return -1;

    char **nodes = (char **)malloc((bankSize + 1) * sizeof(char *));
    int count = 0;
    nodes[count++] = startGene;
    for (int i = 0; i < bankSize; ++i) nodes[count++] = bank[i];

    int dist[11];
    int used[11] = {0};
    for (int i = 0; i < count; ++i) dist[i] = -1;
    dist[0] = 0;

    int queue[11], head = 0, tail = 0;
    queue[tail++] = 0;
    const char bases[] = "ACGT";

    while (head < tail) {
        int u = queue[head++];
        if (strcmp(nodes[u], endGene) == 0) {
            int ans = dist[u];
            free(nodes);
            return ans;
        }
        for (int v = 0; v < count; ++v) {
            if (dist[v] != -1) continue;
            int diff = 0;
            for (int i = 0; i < 8; ++i) {
                if (nodes[u][i] != nodes[v][i] && ++diff > 1) break;
            }
            if (diff == 1) {
                dist[v] = dist[u] + 1;
                queue[tail++] = v;
            }
        }
    }

    free(nodes);
    return -1;
}

